class Data extends ChangeNotifier{SharedPreferences? p;List<Map<String,dynamic>> shops=[];int active=0;bool get ready=>p!=null;bool get has=>shops.isNotEmpty;Map<String,dynamic> get shop=>has?shops[active]:{};List<Map<String,dynamic>> rows(String k){final x=shop[k];return x is List?x.whereType<Map>().map((v)=>Map<String,dynamic>.from(v)).toList():[];}Future<void> load()async{p=await SharedPreferences.getInstance();try{final x=jsonDecode(p!.getString('rf')??'[]');if(x is List)shops=x.whereType<Map>().map((v)=>Map<String,dynamic>.from(v)).toList();}catch(_){shops=[];}active=p!.getInt('active')??0;if(active>=shops.length)active=0;notifyListeners();}Future<void> save()async{await p!.setString('rf',jsonEncode(shops));await p!.setInt('active',active);notifyListeners();}Future<void> shopAdd(Map<String,dynamic> x)async{shops.add({...x,'id':id(),'items':[],'customers':[],'issues':[],'returns':[]});active=shops.length-1;await save();}Future<void> shopEdit(int i,Map<String,dynamic>x)async{shops[i].addAll(x);await save();}Future<void> shopDelete(int i)async{shops.removeAt(i);if(active>=shops.length)active=shops.isEmpty?0:shops.length-1;await save();}Future<void> add(String k,Map<String,dynamic>x)async{(shop[k] as List).add(x);await save();}Future<void> edit(String k,int i,Map<String,dynamic>x)async{(shop[k] as List)[i]=x;await save();}Future<void> del(String k,int i)async{(shop[k] as List).removeAt(i);await save();}}
Future<void> push(BuildContext c,Widget w)=>Navigator.push(c,MaterialPageRoute(builder:(_)=>w));
